const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const root=__dirname;
const hash=(file,algorithm='sha256')=>crypto.createHash(algorithm).update(fs.readFileSync(file)).digest('hex');
function readAccessor(g,buffers,index){const a=g.accessors[index],v=g.bufferViews[a.bufferView],buffer=buffers[v.buffer],n={SCALAR:1,VEC2:2,VEC3:3,VEC4:4}[a.type];const spec={5121:[1,'readUInt8'],5123:[2,'readUInt16LE'],5125:[4,'readUInt32LE'],5126:[4,'readFloatLE']}[a.componentType];if(!spec)throw Error('Unsupported accessor');const start=(v.byteOffset||0)+(a.byteOffset||0),stride=v.byteStride||spec[0]*n;return Array.from({length:a.count},(_,i)=>Array.from({length:n},(_,j)=>buffer[spec[1]](start+i*stride+j*spec[0])));}
function exportObj(id,meshIndex,outName,flat){const dir=path.join(root,id),g=JSON.parse(fs.readFileSync(path.join(dir,id+'_2k.gltf'))),buffers=g.buffers.map(b=>fs.readFileSync(path.join(dir,b.uri)));const mesh=g.meshes[meshIndex];const parts=mesh.primitives.map(p=>({p,pos:readAccessor(g,buffers,p.attributes.POSITION),normal:p.attributes.NORMAL===undefined?null:readAccessor(g,buffers,p.attributes.NORMAL),uv:p.attributes.TEXCOORD_0===undefined?null:readAccessor(g,buffers,p.attributes.TEXCOORD_0),indices:readAccessor(g,buffers,p.indices).flat()}));const all=parts.flatMap(p=>p.pos);const min=[0,1,2].map(i=>Math.min(...all.map(p=>p[i]))),max=[0,1,2].map(i=>Math.max(...all.map(p=>p[i]))),center=min.map((x,i)=>(x+max[i])/2),size=min.map((x,i)=>max[i]-x),scale=1/Math.max(...size);const map=p=>flat?[p[2],p[0],p[1]]:p;let obj=['# Derived from Poly Haven '+id+' / CC0','mtllib '+outName+'.mtl','o '+outName],offset=1,tris=0;for(const {p,pos,normal,uv,indices} of parts){if(p.mode!==undefined&&p.mode!==4)throw Error('Non-triangle');obj.push('g '+g.materials[p.material].name);for(const v of pos){const q=map(v.map((x,i)=>(x-center[i])*scale));obj.push('v '+q.map(x=>x.toFixed(8)).join(' '));}for(const v of uv||pos.map(()=>[0,0]))obj.push('vt '+v[0].toFixed(8)+' '+(1-v[1]).toFixed(8));for(const v of normal||pos.map(()=>[0,1,0]))obj.push('vn '+map(v).map(x=>x.toFixed(8)).join(' '));obj.push('usemtl '+g.materials[p.material].name);for(let i=0;i<indices.length;i+=3){obj.push('f '+indices.slice(i,i+3).map(j=>`${j+offset}/${j+offset}/${j+offset}`).join(' '));tris++;}offset+=pos.length;}
let mtl=[];for(const mat of g.materials){mtl.push('newmtl '+mat.name,'Ka 0.05 0.05 0.05','Kd 1 1 1','Ks 0.05 0.05 0.05','Ns 40');if(mat.pbrMetallicRoughness?.baseColorTexture!==undefined){const t=g.textures[mat.pbrMetallicRoughness.baseColorTexture.index];mtl.push('map_Kd '+g.images[t.source].uri);}if(mat.normalTexture){const t=g.textures[mat.normalTexture.index];mtl.push('map_Bump '+g.images[t.source].uri);}mtl.push('');}fs.writeFileSync(path.join(dir,outName+'.obj'),obj.join('\n')+'\n');fs.writeFileSync(path.join(dir,outName+'.mtl'),mtl.join('\n'));
return {file:id+'/'+outName+'.obj',meshIndex,sourceMesh:mesh.name,triangleCount:tris,vertexCount:offset-1,originalMeshBounds:{min,max,size},transformation:{center,uniformScale:scale,axisMapping:flat?'newXYZ = oldZXY; lay book flat with thickness on Y':'identity axes; centered and largest extent normalized to 1'},materials:g.materials.map(m=>m.name),sha256:hash(path.join(dir,outName+'.obj'))};}
const derived=[];
derived.push(exportObj('book_encyclopedia_set_01',13,'LawBook_SourceBook14_Flat',true));
derived.push(exportObj('book_encyclopedia_set_01',13,'LawBook_SourceBook14_Upright',false));
for(const id of ['rock_07','rock_09'])if(fs.existsSync(path.join(root,id,id+'_2k.gltf')))derived.push(exportObj(id,0,id+'_Centered',false));
const acquisitions=[];
for(const id of ['book_encyclopedia_set_01','rock_07','rock_09']){const metaFile=path.join(root,id==='book_encyclopedia_set_01'?'book-info.json':id+'-info.json'),filesFile=path.join(root,id==='book_encyclopedia_set_01'?'book-files.json':id+'-files.json');if(!fs.existsSync(metaFile))continue;const meta=JSON.parse(fs.readFileSync(metaFile)),api=JSON.parse(fs.readFileSync(filesFile));const entries=[];for(const format of ['gltf','fbx']){const item=api[format]?.['2k']?.[format];if(!item)continue;for(const [relative,record] of [[id+'_2k.'+format,item],...Object.entries(item.include||{})]){const file=path.join(root,id,relative);if(!fs.existsSync(file))throw Error('Missing '+file);const md5=hash(file,'md5');if(record.md5&&record.md5!==md5)throw Error('MD5 mismatch '+file);entries.push({file:id+'/'+relative,url:record.url,bytes:fs.statSync(file).size,md5,officialMd5:record.md5,sha256:hash(file)});}}acquisitions.push({id,title:meta.name,authors:meta.authors,source:'https://polyhaven.com/a/'+id,license:'CC0 1.0',licenseUrl:'https://polyhaven.com/license',originalFilesAcquired:true,sourceTriangleCount:meta.polycount,files:entries,preview:{file:id+'/official-preview.png',url:'https://cdn.polyhaven.com/asset_img/primary/'+id+'.png?height=720',forSourceLinkedReviewOnly:true}});}
const manifest={date:'2026-11-13',scope:'Free original prop acquisition; canonical Unity not modified',acquisitions,derived,notes:['Book source is an encyclopedia, not a historic law book. Law-book label/cover ornament is a proposed game adaptation.','Book 14 selected as a thick independent closed volume; source 20 books remain preserved.','Rock originals have no prebuilt sword slot. A physical cavity or insert plate must be added by implementation.','OBJ export preserves source geometry/UV/normals, flips UV V for OBJ, centers and uniformly normalizes largest extent to 1. Flat book uses proper cyclic axis rotation.','glTF and FBX plus PBR originals preserved; OBJ MTL carries albedo/normal only. Unity smoothness/metallic setup should use separately supplied original maps.','Official preview pictures are research reference images, not asserted to have the same license as source 3D assets.']};
fs.writeFileSync(path.join(root,'acquisition-manifest.json'),JSON.stringify(manifest,null,2));fs.writeFileSync(path.join(root,'CREDITS.txt'),acquisitions.map(a=>a.title+' — '+Object.keys(a.authors||{}).join(', ')+'\nSource: '+a.source+'\nLicense: CC0 1.0 / https://polyhaven.com/license\nChanges: see acquisition-manifest.json\n').join('\n'));
console.log(JSON.stringify({models:acquisitions.map(a=>({id:a.id,files:a.files.length,triangles:a.sourceTriangleCount})),derived:derived.map(d=>({file:d.file,triangles:d.triangleCount,bounds:d.originalMeshBounds.size}))},null,2));
